const NL = String.fromCharCode(10);
const FENCE = String.fromCharCode(96, 96, 96);
const b = $('Build Agent Brief').first().json;
const j = $input.first().json || {};
let attempt = 0;
try { const p = $('Validate JSON Contract').first().json; if (p && typeof p.attempt === 'number') attempt = p.attempt + 1; } catch (e) { attempt = 0; }

let raw = null; let parseError = null;
if (j.error) parseError = 'model_error';
else { const c = j.output && j.output[0] && j.output[0].content && j.output[0].content[0]; raw = c ? c.text : null; }
let out = null;
if (raw && typeof raw === 'object') out = raw;
else if (typeof raw === 'string') {
  let s = raw.trim();
  if (s.startsWith(FENCE)) s = s.slice(s.indexOf(NL) + 1);
  if (s.endsWith(FENCE)) s = s.slice(0, -3);
  try { out = JSON.parse(s.trim()); } catch (e) { parseError = 'malformed_json'; }
} else if (!parseError) parseError = 'empty_output';

const issues = [];
if (out) {
  b.required_keys.forEach(k => { const v = out[k]; if (v === undefined || v === null || v === '' || (Array.isArray(v) && !v.length)) issues.push('missing_or_empty:' + k); });
  ['claims', 'brd_sections_addressed', 'ambiguities', 'assumptions'].forEach(k => { if (!Array.isArray(out[k])) issues.push('not_array:' + k); });
  if (b.agent_name === 'tech_stack' && Array.isArray(out.options) && (out.options.length < 2 || out.options.length > 3)) issues.push('options_must_be_2_to_3');
}
const schemaValid = !!out && !parseError && issues.length === 0;
const claims = out && Array.isArray(out.claims) ? out.claims : [];
const valid = new Set(b.valid_source_ids);
const cited = []; const invalid = [];
claims.forEach((c, i) => {
  const s = Array.isArray(c && c.sources) ? c.sources.map(x => String(x).trim()) : [];
  const bad = s.filter(x => !valid.has(x));
  if (bad.length) invalid.push({ claim_index: i, ids: bad });
  if (s.some(x => valid.has(x))) cited.push(i);
});
const addressed = new Set((out && Array.isArray(out.brd_sections_addressed) ? out.brd_sections_addressed : []).map(String));
const triggers = [];
if (parseError) triggers.push('schema:' + parseError);
if (issues.length) triggers.push('schema:' + issues.join('|'));
if (invalid.length) triggers.push('hallucination:invalid_citation_ids');
if (!b.rag_hits) triggers.push('no_rag_hits');
const needsRetry = !schemaValid && attempt < 1;
if (!schemaValid && !needsRetry) triggers.push('schema_contract_failed_after_retry');

return [{ json: {
  run_id: b.run_id, agent_name: b.agent_name, agent_role: b.agent_role, cycle: b.cycle, reused: false,
  attempt: attempt, needs_retry: needsRetry,
  repair_prompt: 'Your previous response FAILED JSON-schema contract validation (' + (parseError || issues.join(', ')) + '). Return ONE corrected JSON object only, matching the schema exactly.' + NL + NL + '=== PREVIOUS RESPONSE ===' + NL + (typeof raw === 'string' ? raw.slice(0, 8000) : JSON.stringify(raw || {}).slice(0, 8000)) + NL + NL + b.user_prompt,
  output: out, schema_valid: schemaValid, schema_issues: parseError ? [parseError].concat(issues) : issues,
  json_repair_attempts: attempt, claims_count: claims.length, cited_indexes: cited, invalid_citations: invalid,
  missing_sections: b.routed_ids.filter(id => !addressed.has(id)), routed_ids: b.routed_ids,
  rag_hits: b.rag_hits, input_hash: b.input_hash, exec_ms: Date.now() - b.start_ms,
  guardrail_triggers: triggers, output_text: JSON.stringify(out || {}),
} }];
